# ======================================================================================
# SQ_ACC pre-study: pick the sum-of-squares implementation ONCE, then hold it fixed so
# the fused and unfused tuning grids are the same size (fairness rule 2).
# ======================================================================================
def sq_study(prob: Problem) -> tuple[dict, list]:
    cfgs_r = [
        dict(BLOCK_M=64, BLOCK_N=256, BLOCK_K=32, num_warps=4, num_stages=2, GROUP_M=8),
        dict(BLOCK_M=64, BLOCK_N=256, BLOCK_K=64, num_warps=4, num_stages=2, GROUP_M=8),
        dict(BLOCK_M=128, BLOCK_N=128, BLOCK_K=32, num_warps=8, num_stages=2, GROUP_M=8),
        dict(BLOCK_M=128, BLOCK_N=256, BLOCK_K=64, num_warps=8, num_stages=2, GROUP_M=8),
    ]
    cfgs_m = [
        dict(BLOCK_M=64, BLOCK_N=128, BLOCK_K=32, num_warps=8, num_stages=2, GROUP_M=8),
        dict(BLOCK_M=128, BLOCK_N=128, BLOCK_K=32, num_warps=8, num_stages=2, GROUP_M=8),
        dict(BLOCK_M=128, BLOCK_N=128, BLOCK_K=64, num_warps=8, num_stages=2, GROUP_M=8),
        dict(BLOCK_M=64, BLOCK_N=256, BLOCK_K=64, num_warps=8, num_stages=2, GROUP_M=8),
    ]
    tab, pick = [], {}
    for tag, cfgs, mk in (
        ("router", cfgs_r, prob.router_fused),
        ("moe", cfgs_m, prob.moe_fused),
    ):
        tot = {False: 0.0, True: 0.0}
        for cfg in cfgs:
            for sq in (False, True):
                try:
                    t = bench_chain([mk(cfg, sq)], 4, 12).p50_ms
                except Exception as exc:  # noqa: BLE001
                    t = None
                    tab.append((tag, cfg, sq, None, str(exc)[:120]))
                if t is not None:
                    tab.append((tag, cfg, sq, t, None))
                    tot[sq] += t
        pick[tag] = tot[True] < tot[False]
        print(
            f"  SQ study [{tag}]: reduce-per-step {tot[False]:.4f} ms total vs "
            f"tile-accumulate {tot[True]:.4f} ms -> SQ_ACC={pick[tag]}",
            flush=True,
        )
    return pick, tab

