        c=dict(k)
        s=f"BM{c['BLOCK_M']} BN{c['BLOCK_N']} BK{c['BLOCK_K']} w{c['num_warps']} s{c['num_stages']} GM{c['GROUP_M']}"
        print(f"  {s:<95}{fu[k]:>9.3f}{ff[k]:>9.3f}{ff[k]/fu[k]:>7.2f}")
    # router
    fu={tuple(sorted(c.items())):m for c,m,e in t["router_unfused"]["coarse"]["table"]+t["router_unfused"]["refine"]["table"] if m}
